from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    outside = set()
    q = deque()

    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and (nr, nc) not in outside):
                outside.add((nr, nc))
                q.append((nr, nc))

    enclosed = {(r, c) for r in range(h) for c in range(w)
                if grid[r][c] == 0 and (r, c) not in outside}

    boundary = set()
    for r, c in enclosed:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                    boundary.add((nr, nc))

    for r, c in enclosed:
        if any((r + dr, c + dc) in boundary
               for dr in (-1, 0, 1) for dc in (-1, 0, 1)):
            out[r][c] = 3

    for r, c in boundary:
        for dr in (-1, 0, 1):
            for dc in range(-1, 2):
                nr, nc = r + dr, c + dc
                if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                        and (nr, nc) in outside):
                    out[nr][nc] = 2

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    fives = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]

    def neighbors(r, c):
        return sum(
            1 for dr in (-1, 0, 1) for dc in (-1, 0, 1)
            if (dr or dc) and 0 <= r + dr < h and 0 <= c + dc < w
            and grid[r + dr][c + dc] != 0
        )

    source = max(fives, key=lambda p: neighbors(*p))
    target = next(p for p in fives if p != source)
    dr, dc = target[0] - source[0], target[1] - source[1]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) != source:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr][nc] = grid[r][c]
    return out

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Each object is a diamond whose four cardinal tips are color 2.
    centers = [
        (r, c)
        for r in range(1, h - 1)
        for c in range(1, w - 1)
        if grid[r - 1][c] == grid[r + 1][c] == grid[r][c - 1] == grid[r][c + 1] == 2
    ]

    # Join diamonds whose centers share a row or column.
    for i, (r1, c1) in enumerate(centers):
        for r2, c2 in centers[i + 1:]:
            if r1 == r2:
                for c in range(min(c1, c2) + 2, max(c1, c2) - 1):
                    if out[r1][c] == 0:
                        out[r1][c] = 1
            elif c1 == c2:
                for r in range(min(r1, r2) + 2, max(r1, r2) - 1):
                    if out[r][c1] == 0:
                        out[r][c1] = 1

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not fours or not sixes:
        return out

    rmin = min(r for r, c in fours)
    rmax = max(r for r, c in fours)
    cmin = min(c for r, c in fours)
    cmax = max(c for r, c in fours)
    srmin = min(r for r, c in sixes)
    srmax = max(r for r, c in sixes)
    scmin = min(c for r, c in sixes)
    scmax = max(c for r, c in sixes)

    for r, c in sixes:
        out[r][c] = 0

    # Reflect toward the 6-shape along the separated axis.
    if cmax < scmin or scmax < cmin:
        for r, c in fours:
            nc = 2 * cmax + 1 - c if cmax < scmin else 2 * cmin - 1 - c
            if 0 <= nc < w:
                out[r][nc] = 4
    else:
        for r, c in fours:
            nr = 2 * rmax + 1 - r if rmax < srmin else 2 * rmin - 1 - r
            if 0 <= nr < h:
                out[nr][c] = 4

    return out

def transform(grid):
    n = len(grid)
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]

    for r in range(n):
        for c in range(n):
            if original[r][c] != 2:
                continue

            # The pattern is symmetric under the square's reflections and rotations.
            candidates = [
                (c, r),
                (n - 1 - r, c),
                (r, n - 1 - c),
                (n - 1 - r, n - 1 - c),
                (n - 1 - c, n - 1 - r),
                (c, n - 1 - r),
                (n - 1 - c, r),
            ]
            for rr, cc in candidates:
                if original[rr][cc] != 2:
                    out[r][c] = original[rr][cc]
                    break

    return out

