def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the full row of 2s that acts as the barrier.
    barrier = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    if barrier is not None:
        direction = 1 if barrier == 0 else -1
    else:
        barrier_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
        if barrier_col is None:
            return [row[:] for row in grid]
        # This task's examples use a horizontal barrier.
        direction = 1 if barrier_col == 0 else -1

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (0, 2) or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            objects.append((color, cells))

    # Process objects nearest the barrier first.
    if barrier is not None:
        objects.sort(key=lambda obj: min(r for r, c in obj[1]) if direction == 1
                     else -max(r for r, c in obj[1]))
    else:
        objects.sort(key=lambda obj: min(c for r, c in obj[1]) if direction == 1
                     else -max(c for r, c in obj[1]))

    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                out[r][c] = 2

    for color, cells in objects:
        dr, dc = (direction, 0) if barrier is not None else (0, direction)
        shift = 0
        while True:
            nr_shift, nc_shift = shift + dr, shift + dc
            can_move = True
            for r, c in cells:
                nr, nc = r + nr_shift, c + nc_shift
                if not (0 <= nr < h and 0 <= nc < w) or out[nr][nc] != 0:
                    can_move = False
                    break
            if not can_move:
                break
            shift += 1
        for r, c in cells:
            out[r + shift * dr][c + shift * dc] = color

    return out

