def transform(grid):
    sep = next(r for r, row in enumerate(grid) if all(v == 5 for v in row))
    colors = {v for row in grid for v in row if v not in (0, 5)}
    counts = {}
    for color in colors:
        above = sum(row.count(color) for row in grid[:sep])
        below = sum(row.count(color) for row in grid[sep + 1:])
        counts[color] = abs(above - below)
    chosen = max(colors, key=lambda c: (counts[c], -c))
    return [[chosen, chosen], [chosen, chosen]]

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            min_r = min(y for y, x in cells)
            min_c = min(x for y, x in cells)
            shape = frozenset((y - min_r, x - min_c) for y, x in cells)
            components.append((color, cells, shape))

    matching_colors = {}
    for color, cells, shape in components:
        if color != 1:
            matching_colors.setdefault(shape, color)

    result = [row[:] for row in grid]
    for color, cells, shape in components:
        if color == 1 and shape in matching_colors:
            replacement = matching_colors[shape]
            for r, c in cells:
                result[r][c] = replacement
    return result

def transform(grid):
    h, w = len(grid), len(grid[0])
    outside = set()
    stack = []

    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                stack.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and (nr, nc) not in outside):
                outside.add((nr, nc))
                stack.append((nr, nc))

    result = [row[:] for row in grid]
    enclosed = {
        (r, c)
        for r in range(h) for c in range(w)
        if grid[r][c] == 0 and (r, c) not in outside
    }
    colors = {3: 8, 5: 4, 7: 3}

    while enclosed:
        start = enclosed.pop()
        component = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if (nr, nc) in enclosed:
                    enclosed.remove((nr, nc))
                    component.add((nr, nc))
                    stack.append((nr, nc))

        size = max(
            max(r for r, c in component) - min(r for r, c in component) + 1,
            max(c for r, c in component) - min(c for r, c in component) + 1
        )
        color = colors.get(size, 8)
        for r, c in component:
            result[r][c] = color

    return result

def transform(grid):
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    seen = set()

    def component(sr, sc):
        if not (0 <= sr < h and 0 <= sc < w) or src[sr][sc] in (0, 5):
            return []
        cells = []
        stack = [(sr, sc)]
        visited = {(sr, sc)}
        while stack:
            r, c = stack.pop()
            cells.append((r, c))
            for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                if (0 <= nr < h and 0 <= nc < w and
                    (nr, nc) not in visited and src[nr][nc] not in (0, 5)):
                    visited.add((nr, nc))
                    stack.append((nr, nc))
        return cells

    # Vertical runs of 5: repeat the adjacent color tile along the run.
    for c in range(w):
        r = 0
        while r < h:
            if src[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and src[r][c] == 5:
                r += 1
            b = r - 1
            if b - a + 1 < 2:
                continue
            for sr in (a, b):
                for sc in (c - 1, c + 1):
                    cells = component(sr, sc)
                    if not cells:
                        continue
                    rs = [x for x, _ in cells]
                    cs = [y for _, y in cells]
                    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
                    th, tw = r1 - r0 + 1, c1 - c0 + 1
                    for rr in range(a, b + 1):
                        for cc in range(c0, c1 + 1):
                            out[rr][cc] = src[r0 + (rr-r0) % th][cc]
                    break
                else:
                    continue
                break

    # Horizontal runs of 5: repeat the adjacent color tile along the run.
    for r in range(h):
        c = 0
        while c < w:
            if src[r][c] != 5:
                c += 1
                continue
            a = c
            while c < w and src[r][c] == 5:
                c += 1
            b = c - 1
            if b - a + 1 < 2:
                continue
            for sc in (a, b):
                for sr in (r - 1, r + 1):
                    cells = component(sr, sc)
                    if not cells:
                        continue
                    rs = [x for x, _ in cells]
                    cs = [y for _, y in cells]
                    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
                    th, tw = r1 - r0 + 1, c1 - c0 + 1
                    for rr in range(r0, r1 + 1):
                        for cc in range(a, b + 1):
                            out[rr][cc] = src[rr][c0 + (cc-c0) % tw]
                    break
                else:
                    continue
                break

    return out

def transform(grid):
    n = len(grid)
    left = [row[:4] for row in grid]
    right = [row[5:9] for row in grid]

    # If the two shapes overlap, keep the left shape; otherwise combine them.
    if any(left[r][c] and right[r][c] for r in range(n) for c in range(4)):
        return left

    return [
        [left[r][c] if left[r][c] else right[r][c] for c in range(4)]
        for r in range(n)
    ]

def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]

    # The 5 marks the starting position in the output panel.
    mr = mc = 0
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 5:
                mr, mc = r, c - 8
                out[mr][mc] = 5

    # Read the 3x3 tiles down the left group, then down the right group.
    tiles = []
    for left in (0, 4):
        for top in range(0, h - 2, 4):
            color = next(
                (grid[r][c] for r in range(top, top + 3)
                 for c in range(left, left + 3) if grid[r][c] != 0),
                0
            )
            if color:
                tiles.append(color)

    y, x = mr, mc
    for color in tiles:
        if color == 6:
            # Downward stroke, two cells long.
            for _ in range(2):
                y += 1
                if 0 <= y < h and 0 <= x < 7:
                    out[y][x] = color
        else:
            length, direction = {
                1: (3, 1),   # east
                2: (2, -1),  # west
                3: (4, -1),  # west
            }[color]
            y += 1
            for _ in range(length):
                if 0 <= y < h and 0 <= x < 7:
                    out[y][x] = color
                x += direction
            x -= direction

    return out

def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    rows = sorted(r for r, c in points)
    mid = rows[len(rows) // 2]
    left = min(c for r, c in points)
    right = max(c for r, c in points)

    for c in range(left, right + 1):
        if out[mid][c] == 0:
            out[mid][c] = 3
    for r, c in points:
        for rr in range(min(r, mid), max(r, mid) + 1):
            if out[rr][c] == 0:
                out[rr][c] = 3
    return out

