def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0}

    # Each tile is either a full 2x2 square or a 2x2 block with one corner missing.
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            block = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            cells = block & occupied
            if len(cells) == 4:
                pieces.append((cells, 1))
            elif len(cells) == 3:
                missing = next(iter(block - cells))
                # The demos map missing top-left, top-right, bottom-left to 2, 4, 3.
                color = {
                    (r, c): 2,
                    (r, c + 1): 4,
                    (r + 1, c): 3,
                    (r + 1, c + 1): 2,
                }[missing]
                pieces.append((cells, color))

    by_cell = {cell: [] for cell in occupied}
    for cells, color in pieces:
        for cell in cells:
            by_cell[cell].append((cells, color))

    # The number of squares is constrained by 4*s + 3*l = number of cells.
    max_squares = min(len(occupied) // 4, len(occupied) % 3)
    # Try feasible square counts from largest to smallest.
    targets = list(range(max_squares, -1, -1))
    targets = [s for s in targets if (len(occupied) - 4 * s) % 3 == 0]

    for target in targets:
        memo = set()

        def search(remaining, squares_left):
            if not remaining:
                return [] if squares_left == 0 else None
            if squares_left < 0 or 4 * squares_left > len(remaining):
                return None
            key = (frozenset(remaining), squares_left)
            if key in memo:
                return None

            chosen = None
            options_for_chosen = None
            for cell in remaining:
                options = [
                    p for p in by_cell[cell]
                    if p[0] <= remaining and (p[1] != 1 or squares_left > 0)
                ]
                if not options:
                    memo.add(key)
                    return None
                if options_for_chosen is None or len(options) < len(options_for_chosen):
                    chosen, options_for_chosen = cell, options
                    if len(options) == 1:
                        break

            options_for_chosen.sort(key=lambda p: (p[1] != 1, min(p[0])))
            for cells, color in options_for_chosen:
                result = search(remaining - cells, squares_left - (color == 1))
                if result is not None:
                    return [(cells, color)] + result

            memo.add(key)
            return None

        solution = search(occupied, target)
        if solution is not None:
            out = [[0] * w for _ in range(h)]
            for cells, color in solution:
                for r, c in cells:
                    out[r][c] = color
            return out

    return [row[:] for row in grid]

