    if motif is None:
        return out

    for i, r in enumerate(starts):
        for j, c in enumerate(starts):
            has_three = any(grid[x][y] == 3
                            for x in range(r, r+t)
                            for y in range(c, c+t))
            has_pattern = any(grid[x][y] == 2
                              for x in range(r, r+t)
                              for y in range(c, c+t))

            if has_three:
                if motif[i][j] == 2:
                    for a in range(t):
                        for b in range(t):
                            out[r+a][c+b] = motif[a][b]
                    out[r+i][c+j] = 8
            elif has_pattern and motif[i][j] == 2:
                out[r+i][c+j] = 8

    return out
